INSERT IGNORE INTO remittance_corridors SELECT CONCAT(p.id,'-',s.code,'-',t.code),p.id,s.code,t.code FROM remittance_providers p CROSS JOIN currencies s CROSS JOIN currencies t WHERE s.code<>t.code;
